previewCss:
.darma-loader-gift-box {
  position: relative;
  width: 44px;
  height: 48px;
}
.darma-loader-gift-box::before {
  content: "";
  position: absolute;
  bottom: 0;
  left: 50%;
  width: 34px;
  height: 28px;
  margin-left: -17px;
  background: var(--loader-color, #6366f1);
  border-radius: 0 0 3px 3px;
}
.darma-loader-gift-box::after {
  content: "";
  position: absolute;
  bottom: 0;
  left: 50%;
  width: 6px;
  height: 28px;
  margin-left: -3px;
  background: #4338ca;
}
.darma-loader-gift-box i {
  position: absolute;
  bottom: 26px;
  left: 50%;
  width: 40px;
  height: 12px;
  margin-left: -20px;
  background: #4338ca;
  border-radius: 3px;
  transform-origin: center;
  animation: darma-loader-gift-box-pop 1.2s ease-in-out infinite;
}
.darma-loader-gift-box i::before {
  content: "";
  position: absolute;
  top: -8px;
  left: 50%;
  width: 8px;
  height: 8px;
  margin-left: -4px;
  border: 3px solid #4338ca;
  border-radius: 50%;
  box-sizing: border-box;
  box-shadow: -7px 0 0 -1px #4338ca, 7px 0 0 -1px #4338ca;
}
@keyframes darma-loader-gift-box-pop {
  0%, 100% { transform: translateY(0) scaleX(1); }
  50% { transform: translateY(-8px) scaleX(1.05); }
}

